const body = $input.first().json.body || $input.first().json;

if (!body.documentId || !body.businessId) {
  throw new Error('Parámetros requeridos ausentes: documentId y businessId son obligatorios.');
}

// Validar que documentId sea un UUID válido
const uuidRegex = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
if (!uuidRegex.test(body.documentId)) {
  throw new Error(`documentId inválido: "${body.documentId}" no es un UUID. Asegúrate de enviar un UUID v4.`);
}

return {
  json: {
    documentId: body.documentId,
    businessId: body.businessId,
    storagePath: body.storagePath || '',
    originalFilename: body.originalFilename || 'documento',
    mimeType: body.mimeType || 'application/pdf',
    fileUrl: body.fileUrl || '',
    uploadedAt: body.uploadedAt || new Date().toISOString()
  }
};

